boolean awaitFile(Duration timeout) throws InterruptedException {
    long deadline = System.nanoTime() + timeout.toNanos();     // 1. fix the deadline once
    synchronized (lock) {
        while (!fileArrived) {                                  // 2. guard on the condition
            long leftMillis = (deadline - System.nanoTime()) / 1_000_000;
            if (leftMillis <= 0) return false;                  // 3. out of time
            lock.wait(leftMillis);                              // 4. wait only for what's left
        }
        return true;
    }
}

